_start:
    cld
    mov rbx, rsp
    xor edi, edi
    mov esi, MAP_BYTES
    mov edx, 3
    mov r10d, 34
    mov r8, -1
    xor r9d, r9d
    mov eax, 9
    syscall
    cmp rax, -4095
    jae bare_fatal
    mov r15, rax
    lea rax, [r15 + 1168]
    mov [r15 + 1176], rax
    cmp qword ptr [rbx], 3
    jne argv_fatal
    mov rdi, [rbx + 16]
    lea rsi, [rip + state_option]
    call cstr_equal
    test eax, eax
    jz argv_fatal
    mov rdi, [rbx + 24]
    mov [r15 + 704], rdi
    call cstr_length
    mov [r15 + 712], rax
    lea rax, [rbx + 40]
    mov [r15 + 648], rax
    lea rdi, [rip + env_state]
    call find_environment
    mov [r15 + 720], rax
    mov [r15 + 728], rdx
    test rax, rax
    jz environment_xdg
    or qword ptr [r15 + 640], 1
environment_xdg:
    lea rdi, [rip + env_xdg]
    call find_environment
    mov [r15 + 736], rax
    mov [r15 + 744], rdx
    test rax, rax
    jz environment_home
    or qword ptr [r15 + 640], 2
environment_home:
    lea rdi, [rip + env_home]
    call find_environment
    mov [r15 + 752], rax
    mov [r15 + 760], rdx
    test rax, rax
    jz environment_temp
    or qword ptr [r15 + 640], 4
environment_temp:
    lea rdi, [rip + env_temp]
    call find_environment
    mov [r15 + 768], rax
    mov [r15 + 776], rdx
    test rax, rax
    jz config_frame
    or qword ptr [r15 + 640], 8
config_frame:
    lea rdi, [r15 + INPUT]
    mov rax, 0x3130434746435248 /* HRCFGC01 */
    mov [rdi], rax
    mov rax, [r15 + 640]
    mov [rdi + 8], rax
    xor ebx, ebx
config_lengths:
    mov rax, rbx
    shl rax, 4
    mov rax, [r15 + rax + 712]
    mov [rdi + rbx*8 + 16], rax
    inc rbx
    cmp rbx, 5
    jne config_lengths
    mov qword ptr [rdi + 56], 0
    add rdi, 64
    xor ebx, ebx
config_bytes:
    mov rax, rbx
    shl rax, 4
    mov rsi, [r15 + rax + 704]
    mov rcx, [r15 + rax + 712]
    rep movsb
    inc rbx
    cmp rbx, 5
    jne config_bytes
    lea rax, [r15 + INPUT]
    sub rdi, rax
    mov [r15 + 24], rdi
    lea rax, [r15 + ROOT_WORK + FOOTER]
    mov qword ptr [rax + 120], 0
    jmp owner_resume

/* Framing is fixed; the two HIA owners make all public protocol decisions. */
frame_next:
    jmp pf_loop
pf_serial_frame_next:
    mov rdi, r15
    call ap_deadline
    test eax, eax
    jz ph_frame_live
    mov rdi, r15
    call public_async_abandon
    jmp config_eof
ph_frame_live:
    mov rdi, r15
    call public_async_next
    test eax, eax
    jnz mcp_resume
    mov rax, [r15 + AP_SLOT]
    cmp qword ptr [rax + 80], 0
    jne config_eof
    mov rcx, [r15 + 816]
    test rcx, rcx
    jz frame_scan
    mov rdx, [r15 + 800]
    cmp rcx, rdx
    ja fatal
    sub rdx, rcx
    lea rdi, [r15 + INPUT]
    lea rsi, [rdi + rcx]
    mov rcx, rdx
    rep movsb
    mov [r15 + 800], rdx
    mov qword ptr [r15 + 808], 0
    mov qword ptr [r15 + 816], 0
frame_scan:
    mov rcx, [r15 + 808]
    mov rdx, [r15 + 800]
    lea rsi, [r15 + INPUT]
frame_scan_byte:
    cmp rcx, rdx
    jae frame_need_input
    cmp byte ptr [rsi + rcx], 10
    je frame_found
    inc rcx
    jmp frame_scan_byte
frame_found:
    lea rax, [rcx + 1]
    mov [r15 + 816], rax
    jmp prepare_line
frame_need_input:
    mov [r15 + 808], rcx
    cmp qword ptr [r15 + 824], 0
    jne frame_final_line
    cmp rdx, 8388610
    jae fatal
    mov ecx, 8388610
    sub rcx, rdx
    cmp rcx, 65536
    jbe frame_read_bounded
    mov ecx, 65536
frame_read_bounded:
    add rsi, rdx
    mov rdx, rcx
    xor edi, edi
    xor eax, eax
    syscall
    cmp rax, -4
    je frame_scan
    cmp rax, -4095
    jae fatal
    test rax, rax
    jz frame_input_eof
    add [r15 + 800], rax
    jmp frame_scan
frame_input_eof:
    mov qword ptr [r15 + 824], 1
    jmp frame_scan
frame_final_line:
    test rdx, rdx
    jz frame_eof
    mov [r15 + 816], rdx
    mov rcx, rdx
prepare_line:
    test rcx, rcx
    jz frame_next
    lea rsi, [r15 + INPUT]
    cmp byte ptr [rsi + rcx - 1], 13
    jne line_ready
    dec rcx
line_ready:
    test rcx, rcx
    jz frame_next
    cmp rcx, 8388608
    ja fatal
    mov [r15 + 24], rcx
    mov edi, MESSAGE_INPUT + 24
    add rdi, r15
    rep movsb
    mov edi, MESSAGE_INPUT
    add rdi, r15
    mov rax, 0x313030514a435248 /* HRCJQ001 */
    mov [rdi], rax
    mov qword ptr [rdi + 8], 1
    mov rsi, [r15 + 24]
    mov [rdi + 16], rsi
    add rsi, 24
    mov edx, PROJECTION + 24
    add rdx, r15
    mov ecx, 67108864
    lea r8, [r15 + VALUE_WORK]
    mov r9d, ROOT_WCAP
    call qword ptr [rip + pub_image_message]
    cmp eax, 256
    jb fatal
    cmp eax, 67108864
    ja fatal
    mov edi, PROJECTION
    add rdi, r15
    mov rdx, 0x313030514e435248 /* HRCNQ001 */
    mov [rdi], rdx
    mov qword ptr [rdi + 8], 1
    mov [rdi + 16], rax
    lea rsi, [rax + 24]
    jmp invoke_connection
frame_eof:
    mov edi, PROJECTION
    add rdi, r15
    mov rax, 0x313030514e435248
    mov [rdi], rax
    mov qword ptr [rdi + 8], 2
    mov qword ptr [rdi + 16], 0
    mov esi, 24
invoke_connection:
    mov edx, ADMISSION
    add rdx, r15
    mov ecx, 134217728
    mov r8d, CONNECTION_WORK
    add r8, r15
    mov r9d, ROOT_WCAP
    call qword ptr [rip + pub_image_connection]
    cmp eax, 256
    jb fatal
    cmp eax, 134217728
    ja fatal
    mov [r15 + 904], rax
    mov ebx, ADMISSION
    add rbx, r15
    mov rdx, 0x313030534e435248
    cmp [rbx], rdx
    jne fatal
    mov rdx, [rbx + 16]
    cmp rdx, 1
    ja fatal
    mov [r15 + 912], rdx
    mov rdx, [rbx + 8]
    cmp rdx, 6
    je config_eof
    test rdx, rdx
    jz frame_next
    cmp rdx, 1
    je direct_response
    cmp rdx, 5
    ja fatal
    cmp rdx, 2
    je ph_admit_current
    cmp rdx, 3
    je ph_notify_current
    jmp mcp_resume
ph_admit_current:
    mov rdi, r15
    mov rsi, rbx
    mov rdx, [r15 + 904]
    xor ecx, ecx
    call public_async_admit
    jmp mcp_resume
ph_notify_current:
    mov rcx, [rbx + 80]
    mov r8, [rbx + 88]
    cmp rcx, 256
    jb fatal
    cmp rcx, [r15 + 904]
    ja fatal
    mov rax, [r15 + 904]
    sub rax, rcx
    cmp r8, rax
    ja fatal
    add rcx, rbx
    mov rdi, [r15 + AP_SLOT]
    mov esi, 2
    xor edx, edx
    xor r9d, r9d
    call ap_pool_call
    jmp mcp_resume
direct_response:
    mov rdx, [rbx + 64]
    mov rcx, [rbx + 72]
    cmp rdx, 256
    jb fatal
    cmp rdx, rax
    ja fatal
    sub rax, rdx
    cmp rcx, rax
    ja fatal
    lea rsi, [rbx + rdx]
    mov rdx, rcx
    jmp public_write
config_eof:
    jmp ex_shutdown
config_eof_original:
    mov qword ptr [r15 + 24], 0
    lea rax, [r15 + ROOT_WORK + FOOTER]
    mov qword ptr [rax + 120], 2
    jmp owner_resume

owner_resume:
    cmp qword ptr [r15 + PF_PARENT_SLOT], 0
    jne pf_private_owner
    mov qword ptr [r15 + 80], 0
    lea r13, [r15 + INPUT]
    lea r12, [r15 + OUTPUT]
    mov rsi, [r15 + 24]
    mov ecx, ROOT_OUTPUT_CAP
    cmp qword ptr [r15 + 784], 0
    je owner_context_ready
    mov r13, [r15 + 832]
    mov rsi, [r15 + 840]
    mov r12, [r15 + 848]
    mov rcx, [r15 + 856]
owner_context_ready:
    lea r14, [r15 + ROOT_WORK]
    mov rdi, r13
    mov rdx, r12
    mov r8, r14
    mov r9d, ROOT_WCAP
    call qword ptr [rip + pub_image_owner]
    jmp native_return
mcp_resume:
    mov qword ptr [r15 + 80], 5
    mov r13d, ADMISSION
    add r13, r15
    lea r12, [r15 + OUTPUT]
    lea r14, [r15 + MCP_WORK]
    mov rdi, r13
    mov rsi, [r15 + 904]
    mov rdx, r12
    mov ecx, ROOT_OUTPUT_CAP
    mov r8, r14
    mov r9d, ROOT_WCAP
    call qword ptr [rip + pub_image_mcp]
    jmp native_return
native_resume:
    cmp qword ptr [r15 + 80], 1
    jne fatal
    mov rdi, r13
    mov rsi, [r15 + 96]
    mov rdx, r12
    mov rcx, [r15 + 104]
    mov r8, r14
    mov r9d, WCAP
    call qword ptr [rip + pub_image_fs]
    jmp native_return
json_resume:
    lea r14, [r15 + JSON_WORK]
    mov rdi, r13
    mov rsi, [r15 + 96]
    mov rdx, r12
    mov rcx, [r15 + 104]
    mov r8, r14
    mov r9d, ROOT_WCAP
    call qword ptr [rip + pub_image_json]
    jmp native_return
identity_resume:
    lea r14, [r15 + SHA_WORK]
    mov rdi, r13
    mov rsi, [r15 + 96]
    mov rdx, r12
    mov rcx, [r15 + 104]
    mov r8, r14
    mov r9d, ROOT_WCAP
    call qword ptr [rip + pub_image_identity]
    jmp native_return
validation_resume:
    lea r14, [r15 + REGEX_CONTEXTS]
    mov qword ptr [r14], 3
    mov [r14 + 8], r13
    mov rax, [r15 + 96]
    mov [r14 + 16], rax
    mov [r14 + 24], r12
    mov rax, [r15 + 104]
    mov [r14 + 32], rax
    lea rax, [r15 + VALIDATION_WORK]
    mov [r14 + 40], rax
    mov qword ptr [r14 + 48], ROOT_WCAP
    xor r12d, r12d
    jmp regex_invoke
native_return:
    mov edx, eax
    cmp rax, rdx
    jne fatal
    mov edx, 0xffffffe0
    cmp rax, rdx
    je call_dispatch
    mov edx, 0xfffffff0
    cmp rax, rdx
    je effect_dispatch_checked
    cmp qword ptr [r15 + 80], 5
    je mcp_completed
    cmp qword ptr [r15 + 80], 6
    je execution_completed
    cmp qword ptr [r15 + 80], 7
    je execution_child_completed
    cmp qword ptr [r15 + 80], 8
    je execution_child_completed
    cmp qword ptr [r15 + 80], 0
    jne child_completed
    cmp qword ptr [r15 + 784], 0
    jne mcp_owner_completed
    cmp rax, ROOT_OUTPUT_CAP
    ja fatal
    cmp qword ptr [r14 + FOOTER + 120], 2
    je shutdown_completed
    cmp qword ptr [r14 + FOOTER + 120], 0
    je startup_completed
    jmp fatal /* No external binary-query production path. */
mcp_completed:
    cmp rax, ROOT_OUTPUT_CAP
    ja fatal
    cmp eax, 8
    jb ex_mcp_untyped
    mov rdx, 0x3153455243505248
    cmp [r15 + OUTPUT], rdx
    je ex_wire
ex_mcp_untyped:
    mov rdx, rax
    lea rsi, [r15 + OUTPUT]
public_write:
    push rsi
    push rdx
    mov rdi, r15
    call public_async_response
    pop rdx
    pop rsi
    test eax, eax
    jz public_written
    test rdx, rdx
    jz public_written
    mov edi, 1
    call write_exact
    test eax, eax
    jnz fatal
    mov edi, 1
    lea rsi, [rip + newline]
    mov edx, 1
    call write_exact
    test eax, eax
    jnz fatal
public_written:
    cmp qword ptr [r15 + PF_PARENT_SLOT], 0
    jne pf_written
    cmp qword ptr [r15 + 912], 0
    jne config_eof
    jmp frame_next
mcp_owner_completed:
    cmp qword ptr [r15 + 784], 3
    je ex_config_return
    cmp rax, [r15 + 856]
    ja fatal
    cmp qword ptr [r15 + 784], 2
    je execution_owner_completed
    lea rdx, [r15 + MCP_WORK + FOOTER]
    mov [rdx + 80], rax
    mov rax, [r15 + 792]
    mov [rdx + 88], rax
    mov qword ptr [rdx + 96], 1
    mov qword ptr [r15 + 784], 0
    jmp mcp_resume
startup_completed:
    test eax, eax
    jz ex_initialize
    cmp rax, 32
    jb fatal
    lea rsi, [r15 + OUTPUT]
    mov rdx, 0x31304d4746435248 /* HRCFGM01 */
    cmp [rsi], rdx
    jne fatal
    sub rax, 32
    cmp [rsi + 24], rax
    jne fatal
    mov rdx, rax
    add rsi, 32
    mov edi, 2
    call write_exact
    mov edi, 2
    lea rsi, [rip + newline]
    mov edx, 1
    call write_exact
    mov ebp, 78
    jmp cleanup_all
shutdown_completed:
    test eax, eax
    jnz fatal
    jmp finish_ok
effect_dispatch_checked:
    cmp qword ptr [r15 + 80], 1
    jne fatal
    jmp effect_dispatch

child_completed:
    mov edx, 0xffff0000
    cmp rax, rdx
    jae child_result_ok
    cmp rax, [r15 + 104]
    ja fatal
child_result_ok:
    lea rdx, [r15 + ROOT_WORK + FOOTER]
    mov [rdx + 80], rax
    mov rax, [r15 + 88]
    mov [rdx + 88], rax
    mov qword ptr [rdx + 96], 1
    jmp owner_resume

/* Closed calls from registry5 to installed config0 and execution6.
 * Execution6 can call only JSON7, config0/op4 and core8. No caller-supplied
 * table, code address, configuration event, file descriptor or syscall. */
mcp_call_dispatch:
    cmp qword ptr [r15 + 784], 0
    jne fatal
    cmp qword ptr [r15 + 872], 0
    jne fatal
    lea rdx, [r15 + MCP_WORK + FOOTER]
    mov rax, 0x31304c4143414948
    cmp [rdx], rax
    jne fatal
    mov rax, [r15 + 792]
    inc rax
    jz fatal
    cmp [rdx + 8], rax
    jne fatal
    mov [r15 + 792], rax
    cmp qword ptr [rdx + 24], 2
    jne fatal
    cmp qword ptr [rdx + 48], 2
    jne fatal
    cmp qword ptr [rdx + 64], 67108864
    jne fatal
    mov rax, [rdx + 72]
    or rax, [rdx + 80]
    or rax, [rdx + 88]
    or rax, [rdx + 96]
    or rax, [rdx + 104]
    jnz fatal
    mov rax, [rdx + 16]
    cmp qword ptr [rdx + 56], 100667392
    jne fatal
    cmp rax, 7
    je pr_mcp_read_call
    cmp rax, 6
    je mcp_execution_call
    test rax, rax
    jnz fatal
    cmp qword ptr [rdx + 32], 33550336
    jne fatal
    cmp qword ptr [rdx + 40], 24
    jne fatal
    lea rax, [r15 + MCP_WORK + 33550336]
    mov rdx, 0x3130514746435248
    cmp [rax], rdx
    jne fatal
    cmp qword ptr [rax + 8], 1
    jb fatal
    cmp qword ptr [rax + 8], 2
    ja fatal
    cmp qword ptr [rax + 16], 0
    jne fatal
    mov [r15 + 832], rax
    mov qword ptr [r15 + 840], 24
    lea rax, [r15 + MCP_WORK + 100667392]
    mov [r15 + 848], rax
    mov qword ptr [r15 + 856], 67108864
    mov qword ptr [r15 + 784], 1
    lea rax, [r15 + ROOT_WORK + FOOTER]
    mov qword ptr [rax + 120], 1
    jmp owner_resume

mcp_execution_call:
    cmp qword ptr [rdx + 32], 33554432
    jne fatal
    mov rsi, [rdx + 40]
    cmp rsi, 26
    jb fatal
    cmp rsi, 67108864
    ja fatal
    lea r13, [r15 + MCP_WORK + 33554432]
    mov rax, 0x3130514552535848
    cmp [r13], rax
    jne fatal
    cmp qword ptr [r13 + 8], 1
    jb fatal
    cmp qword ptr [r13 + 8], 3
    jbe ph_route_allowed
    cmp qword ptr [r13 + 8], 6
    je ph_route_allowed
    cmp qword ptr [r13 + 8], 7
    je ph_route_allowed
    cmp qword ptr [r13 + 8], 10
    je ph_route_allowed
    cmp qword ptr [r13 + 8], 11
    jne fatal
ph_route_allowed:
    mov rax, rsi
    sub rax, 24
    cmp [r13 + 16], rax
    jne fatal
    mov [r15 + 880], rsi
    jmp ex_begin
execution_resume:
    cmp qword ptr [r15 + 872], 1
    jne fatal
    mov qword ptr [r15 + 80], 6
    lea r13, [r15 + MCP_WORK + 33554432]
    lea r12, [r15 + MCP_WORK + 100667392]
    mov r14d, EXECUTION_WORK
    add r14, r15
    mov rdi, r13
    mov rsi, [r15 + 880]
    mov rdx, r12
    mov ecx, 67108864
    mov r8, r14
    mov r9d, ROOT_WCAP
    call qword ptr [rip + pub_image_execution]
