# Exact raw argv root lookup, not an owner hash or a serialized authority flag.
# rdi=Root,rsi=bytes,rdx=length -> rax=one-based cap or zero.
tk_intent_root_cap:
    push rbx
    mov r8, rsi
    mov r9, rdx
