    test rax, rax
    jnz tk_rdw_fatal_contract
    mov rdi, r13
    mov esi, tk_RDW_R_MAP
    call tk_rdw_unmap
    xor eax, eax
    tk_rdw_epilogue
tk_rdw_destroy_busy:
    call tk_rdw_unlock
    mov eax, tk_RDW_STATE_ERROR
    tk_rdw_epilogue

