# Distinct original collection mutexes; no movable arena escapes its short gate.
tk_async_allocate:
    push rbx
    push r12
    sub rsp, 8
    mov rbx, rdi
    test rbx, 4095
    jnz tk_async_contract_failure
    test rbx, rbx
    jz tk_async_contract_failure
    mov rsi, rbx
    add rsi, 4096
    jc tk_async_contract_failure
    xor edi, edi
    mov edx, 3
    mov r10d, 34
    mov r8, -1
    xor r9d, r9d
    mov eax, 9
    syscall
    cmp rax, -4095
    jae tk_async_contract_failure
    mov r12, rax
    lea rdi, [rax + rbx]
    mov esi, 4096
    xor edx, edx
    mov eax, 10
    syscall
    test rax, rax
    jnz tk_async_contract_failure
    mov rax, r12
    add rsp, 8
    pop r12
    pop rbx
    ret

# rdi=existing shared Audit service root, rsi=existing Config/Intent IG.
