    cmp eax, tk_ASY_GROW
    je tk_async_state_grow
    mov edx, eax
    cmp rax, rdx
    jne tk_async_contract_failure
    cmp eax, 64
    jne tk_async_contract_failure
    mov [rsp], rax
    mov rdi, [rsp + 8]
    call tk_mutex_unlock
    mov rax, [rsp]
    add rsp, 128
    tk_asy_epilogue
tk_async_state_grow:
    mov rax, [rbx]
    mov rax, [rax + 40]
    cmp rax, [rbx + 8]
    jbe tk_async_contract_failure
    mov rdi, [rbx + 8]
    add rdi, rdi
    jc tk_async_contract_failure
    cmp rdi, rax
    cmovb rdi, rax
    add rdi, 4095
    jc tk_async_contract_failure
    and rdi, -4096
