    cmp [rbp + 8], rax
    jne tk_async_contract_failure
    mov [r12 + tk_AIO_SEQ], rax
    cmp qword ptr [rbp + 24], 0
    jne tk_async_contract_failure
    cmp qword ptr [rbp + 32], tk_AIO_REQUEST
    jne tk_async_contract_failure
    cmp qword ptr [rbp + 48], tk_AIO_REPLY
    jne tk_async_contract_failure
    cmp qword ptr [rbp + 56], tk_AIO_REPLY_CAP
    jne tk_async_contract_failure
