    or rax, [rbp + 72]
    or rax, [rbp + 80]
    or rax, [rbp + 88]
    jnz tk_async_contract_failure
    mov rdx, [rbp + 40]
    cmp rdx, 64
    jb tk_async_contract_failure
    cmp rdx, 1056832
    ja tk_async_contract_failure
