# handler(input, length, output, capacity), with the real public root in r15.
pr_handler:
    pr_prologue
    mov [rsp], rdi
    mov [rsp + 8], rsi
    mov [rsp + 16], rdx
    mov [rsp + 24], rcx
    cmp rsi, 24
    jb fatal
    cmp rsi, PR_INPUT_CAPACITY
    ja fatal
    cmp rcx, 32
    jb fatal
    cmp rcx, PR_CAP
    ja fatal
    mov rdi, r15
    call pr_context
    mov r12, rax
    cmp qword ptr [r12 + PR_ACTIVE], 0
    jne fatal
    cmp qword ptr [r12 + PR_CALLER], 0
    jne fatal
    mov qword ptr [r12 + PR_ACTIVE], 1
    mov rax, [rsp + 8]
    mov [r12 + PR_LENGTH], rax
    mov rax, [rsp + 16]
    mov [r12 + PR_TARGET], rax
    mov rax, [rsp + 24]
    mov [r12 + PR_CAPACITY], rax
    lea rdi, [r12 + PR_INPUT]
    mov rsi, [rsp]
    mov rcx, [rsp + 8]
    rep movsb
    lea rdi, [r12 + PR_INPUT]
    mov esi, PR_INPUT_MAPPING
    mov edx, 1
    mov eax, 10
    syscall
    test rax, rax
    jnz fatal
    lea rbp, [r12 + PR_WORK]
pr_handler_resume:
    lea rdi, [r12 + PR_INPUT]
    mov rsi, [r12 + PR_LENGTH]
    lea rdx, [r12 + PR_OUTPUT]
    mov rcx, [r12 + PR_CAPACITY]
    mov r8, rbp
    mov r9d, PR_WORK_BYTES
    call qword ptr [rip + pr_image_handler]
    mov edx, eax
    cmp rax, rdx
    jne fatal
    cmp eax, 0xfffffff0
    je pr_handler_action
    mov [r12 + PR_RESULT], rax
    cmp eax, PR_CAP
    jbe pr_handler_completed
    cmp eax, 0xfffffff0
    jb fatal
    jmp pr_handler_terminal
pr_handler_completed:
    cmp rax, [r12 + PR_CAPACITY]
    ja fatal
    lea rsi, [r12 + PR_OUTPUT]
    mov rdi, [r12 + PR_TARGET]
    mov rcx, rax
    rep movsb
pr_handler_terminal:
    cmp qword ptr [r12 + PR_CALLER], 0
    jne fatal
    cmp qword ptr [r12 + PR_PURE_BUSY], 0
    jne fatal
    lea rdi, [r12 + PR_INPUT]
    mov esi, PR_INPUT_MAPPING
    mov edx, 3
    mov eax, 10
    syscall
    test rax, rax
    jnz fatal
    mov qword ptr [r12 + PR_ACTIVE], 0
    mov qword ptr [r12 + PR_TARGET], 0
    mov qword ptr [r12 + PR_CAPACITY], 0
    mov rax, [r12 + PR_RESULT]
    pr_epilogue

pr_handler_action:
    lea r14, [rbp + PR_ACTION]
    mov rax, 0x3130304148525248
    cmp [r14], rax
    jne fatal
    mov rax, [r12 + PR_SEQUENCE]
    inc rax
    jz fatal
    cmp [r14 + 8], rax
    jne fatal
    mov [r12 + PR_SEQUENCE], rax
    cmp qword ptr [r14 + 24], 0
    jne fatal
    cmp qword ptr [r14 + 32], PR_CHILD_INPUT
    jne fatal
    cmp qword ptr [r14 + 48], PR_CHILD_OUTPUT
    jne fatal
    cmp qword ptr [r14 + 56], PR_CAP
    jne fatal
    mov rax, [r14 + 64]
    or rax, [r14 + 72]
    or rax, [r14 + 80]
    or rax, [r14 + 88]
    jnz fatal
    mov rax, [r14 + 40]
    cmp rax, PR_CAP
    ja fatal
    lea rdi, [r12 + PR_ACTION_COPY]
    mov rsi, r14
    mov ecx, 12
    rep movsq
    lea rdi, [rbp + PR_CHILD_INPUT]
    mov rsi, [r14 + 40]
    lea rdx, [rbp + PR_CHILD_OUTPUT]
    mov ecx, PR_CAP
    mov rax, [r14 + 16]
    cmp rax, 1
    je pr_handler_params
    cmp rax, 2
    je pr_handler_authority
    cmp rax, 3
    je pr_handler_async
    cmp rax, 4
    je pr_handler_read
    cmp rax, 5
    je pr_handler_fallback
    cmp rax, 6
    je pr_handler_fallback
    cmp rax, 7
    je pr_handler_status
    cmp rax, 8
    je pr_handler_value
    cmp rax, 9
    je pr_handler_error
    cmp rax, 10
    je pr_handler_scope
    jmp fatal
pr_handler_params:
    mov rax, [rip + pr_image_params]
    call pr_pure
    jmp pr_handler_ack
pr_handler_authority:
    call pr_authority
    jmp pr_handler_ack
pr_handler_async:
    call pr_async
    jmp pr_handler_ack
pr_handler_read:
    call pr_read
    jmp pr_handler_ack
pr_handler_fallback:
    call pr_async_child
    jmp pr_handler_ack
pr_handler_status:
    mov rax, [rip + pr_image_status]
    call pr_pure
    jmp pr_handler_ack
pr_handler_value:
    mov rax, [rip + pr_image_value]
    call pr_pure
    jmp pr_handler_ack
pr_handler_error:
    mov rax, [rip + pr_image_error]
    call pr_pure
    jmp pr_handler_ack
pr_handler_scope:
    mov rax, [rip + pr_image_scope]
    call pr_pure
pr_handler_ack:
    mov ebx, eax
    cmp rax, rbx
    jne fatal
    cmp eax, PR_CAP
    jbe pr_handler_ack_valid
    cmp eax, 0xfffffff0
    jb fatal
    cmp eax, 0xfffffff0
    je fatal
pr_handler_ack_valid:
    lea rdi, [r12 + PR_ACTION_COPY]
    mov rsi, r14
    mov ecx, 12
    repe cmpsq
    jne fatal
    mov [r14 + 72], rbx
    mov rax, [r12 + PR_SEQUENCE]
    mov [r14 + 64], rax
    jmp pr_handler_resume

# Fixed mapper extensions, all requests and completions remain mapper-owned.
pr_map_getter:
    call pr_early_getter
    jmp ex_mapper_ack
pr_map_async:
    call pr_async
    jmp ex_mapper_ack
pr_map_handler:
    call pr_handler
    jmp ex_mapper_ack

.balign 8
pr_image_getter: .quad 0
pr_image_handler: .quad 0
pr_image_params: .quad 0
pr_image_status: .quad 0
pr_image_value: .quad 0
pr_image_error: .quad 0
pr_image_scope: .quad 0

pr_read_runtime_aborted:
    cmp qword ptr [r12 + PR_ACTIVE], 1
    jne ap_contract
    mov rax, [r12 + PR_CALLER]
    or rax, [r12 + PR_PURE_BUSY]
    jnz ap_contract
    lea rdi, [r12 + PR_INPUT]
    mov esi, PR_INPUT_MAPPING
    mov edx, 3
    mov eax, 10
    syscall
    test rax, rax
    jnz ap_contract
    mov qword ptr [r12 + PR_ACTIVE], 0
    mov qword ptr [r12 + PR_TARGET], 0
    mov qword ptr [r12 + PR_CAPACITY], 0
    jmp ph_runtime_aborted

/* Fixed SDK admission custody. No public frame contains native pointers. */
.equ AP_SLOT, 4000
.equ AP_INPUT, 4096
.equ AP_OUTPUT, 67117056
.equ AP_POOL, 67121152
.equ AP_MESSAGE, 335556608
.equ AP_PROJECTION, 343949312
.equ AP_ADMISSION, 411062272
.equ AP_PARSER, 545280000
.equ AP_GUARD, 813715456
.equ AP_BYTES, 813719552
.equ AP_NODE_HEADER, 4096

public_async_initialize:
    push rbx
    mov rbx, rdi
    cmp qword ptr [rbx + AP_SLOT], 0
    jne ap_contract
    mov edi, AP_BYTES
    call ex_allocate
    mov [rbx + AP_SLOT], rax
    mov rdx, 0x3130544e59534150
    mov [rax], rdx
    mov [rax + 8], rbx
    lea rdi, [rax + AP_GUARD]
    mov esi, 4096
    xor edx, edx
    mov eax, 10
    syscall
    test rax, rax
    jnz ap_contract
    xor eax, eax
    pop rbx
    ret

# P, operation, token, projection pointer, projection bytes, timespec or 0.
ap_pool_call:
    push rbx
    push rbp
    push r12
    push r13
    push r14
    push r15
    sub rsp, 8
    mov rbx, rdi
    mov rbp, rsi
    mov r12, rdx
    mov r13, rcx
    mov r14, r8
    mov r15, r9
    cmp r14, 67108864
    ja ap_contract
    lea rdi, [rbx + AP_INPUT]
    mov rax, 0x313051504d505248
    mov [rdi], rax
    mov [rdi + 8], rbp
    mov [rdi + 16], r12
    mov [rdi + 24], r14
    mov qword ptr [rdi + 32], 0
    mov qword ptr [rdi + 40], 0
    test r15, r15
    jz ap_pool_time_ready
    mov rax, [r15]
    mov [rdi + 32], rax
    mov rax, [r15 + 8]
    mov [rdi + 40], rax
ap_pool_time_ready:
    add rdi, 48
    mov rsi, r13
    mov rcx, r14
    rep movsb
    lea rdi, [rbx + AP_INPUT]
    lea rsi, [r14 + 48]
    lea rdx, [rbx + AP_OUTPUT]
    mov ecx, 64
    call pf_pool_workspace
    mov r9d, 268435456
    call qword ptr [rip + ap_image_pool]
    cmp rax, 64
    jne ap_contract
    mov rdx, 0x313052504d505248
    cmp [rbx + AP_OUTPUT], rdx
    jne ap_contract
    cmp [rbx + AP_OUTPUT + 8], rbp
    jne ap_contract
    mov eax, 64
    add rsp, 8
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbp
    pop rbx
    ret

public_async_cancelled:
    push rbx
    mov rbx, [rdi + AP_SLOT]
    test rbx, rbx
    jz ap_contract
    cmp [rbx + 8], rdi
    jne ap_contract
    mov rax, [rbx + 32]
    test rax, rax
    jz ap_contract
    mov rdx, [rax + 16]
    mov rdi, rbx
    mov esi, 3
    xor ecx, ecx
    xor r8d, r8d
    xor r9d, r9d
    call ap_pool_call
    mov rax, [rbx + AP_OUTPUT + 24]
    cmp rax, 1
    ja ap_contract
    pop rbx
    ret

ap_node_unmap:
    mov rax, 0x3130444e59534150
    cmp [rdi], rax
    jne ap_contract
    mov qword ptr [rdi], 0
    mov rsi, [rdi + 32]
    mov eax, 11
    syscall
    test rax, rax
    jnz ap_contract
    ret

ap_contract:
    mov edi, 70
    mov eax, 231
    syscall
    ud2

ap_image_pool:
    .quad 0

# root, complete admission, bytes, 0 = current / 1 = queue.
public_async_admit:
    push rbx
    push rbp
    push r12
    push r13
    push r14
    push r15
    sub rsp, 8
    mov r15, rdi
    mov r12, rsi
    mov r13, rdx
    mov r14, rcx
    mov rbx, [r15 + AP_SLOT]
    test rbx, rbx
    jz ap_contract
    cmp [rbx + 8], r15
    jne ap_contract
    cmp r14, 1
    ja ap_contract
    cmp r13, 256
    jb ap_contract
    cmp r13, 134217728
    ja ap_contract
    mov rax, 0x313030534e435248
    cmp [r12], rax
    jne ap_contract
    cmp qword ptr [r12 + 8], 2
    jne ap_contract
    cmp qword ptr [r12 + 16], 1
    ja ap_contract
    mov rcx, [r12 + 80]
    mov r8, [r12 + 88]
    cmp rcx, 256
    jb ap_contract
    cmp rcx, r13
    ja ap_contract
    mov rax, r13
    sub rax, rcx
    cmp r8, rax
    ja ap_contract
    add rcx, r12
    mov rdi, rbx
    mov esi, 1
    xor edx, edx
    xor r9d, r9d
    call ap_pool_call
    lea rdi, [r13 + 8191]
    and rdi, -4096
    mov rbp, rdi
    call ex_allocate
    mov [rsp], rax
    mov rdx, 0x3130444e59534150
    mov [rax], rdx
    mov qword ptr [rax + 8], 0
    mov rdx, [rbx + AP_OUTPUT + 16]
    test rdx, rdx
    jz ap_contract
    mov [rax + 16], rdx
    mov [rax + 24], r13
    mov [rax + 32], rbp
    lea rdi, [rax + AP_NODE_HEADER]
    mov rsi, r12
    mov rcx, r13
    rep movsb
    mov rdi, [rsp]
    add rdi, AP_NODE_HEADER
    mov rsi, rbp
    sub rsi, AP_NODE_HEADER
    mov edx, 1
    mov eax, 10
    syscall
    test rax, rax
    jnz ap_contract
    mov rax, [rsp]
    test r14, r14
    jnz ap_admit_queued
    cmp qword ptr [rbx + 32], 0
    jne ap_contract
    cmp qword ptr [rbx + 16], 0
    jne ap_contract
    mov [rbx + 32], rax
