ap_admit_done:
    mov rax, [rax + 16]
    add rsp, 8
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbp
    pop rbx
    ret

public_async_next:
    push rbx
    push r12
    push r15
    mov r15, rdi
    mov rbx, [r15 + AP_SLOT]
