# root -> 0 incomplete, 1 complete line (rsi/rdx), 2 actual EOF.
# The active request's admission and HIA state are in separate mappings.
ap_scan_frame:
    mov r8, rdi
ap_scan_again:
    mov rcx, [r8 + 816]
    test rcx, rcx
    jz ap_scan_start
    mov rdx, [r8 + 800]
    cmp rcx, rdx
    ja ap_contract
    sub rdx, rcx
    lea rdi, [r8 + INPUT]
    lea rsi, [rdi + rcx]
    mov rcx, rdx
    rep movsb
    mov [r8 + 800], rdx
    mov qword ptr [r8 + 808], 0
    mov qword ptr [r8 + 816], 0
ap_scan_start:
    mov rcx, [r8 + 808]
    mov rdx, [r8 + 800]
    lea rsi, [r8 + INPUT]
ap_scan_byte:
    cmp rcx, rdx
    jae ap_scan_incomplete
    cmp byte ptr [rsi + rcx], 10
    je ap_scan_found
    inc rcx
    jmp ap_scan_byte
ap_scan_found:
    lea rax, [rcx + 1]
    mov [r8 + 816], rax
    jmp ap_scan_line
ap_scan_incomplete:
    mov [r8 + 808], rcx
    cmp qword ptr [r8 + 824], 0
    je ap_scan_empty
    test rdx, rdx
    jz ap_scan_eof
    mov [r8 + 816], rdx
    mov rcx, rdx
ap_scan_line:
    test rcx, rcx
    jz ap_scan_again
    cmp byte ptr [rsi + rcx - 1], 13
    jne ap_scan_ready
    dec rcx
ap_scan_ready:
    test rcx, rcx
    jz ap_scan_again
    cmp rcx, 8388608
    ja ap_contract
    mov rdx, rcx
    mov eax, 1
    ret
ap_scan_empty:
    xor eax, eax
    ret
ap_scan_eof:
    mov eax, 2
    ret

# Called only after poll observes readiness on the owned stdin descriptor.
