hp_spawn_error:
    mov [r15 + hp_G_ERROR], rax
    mov ebx, hp_G_OUT
hp_spawn_close_slots:
    lea rdi, [r15 + rbx]
    call hp_close_slot
    add ebx, 8
    cmp ebx, hp_G_ERR_OUT + 8
    jne hp_spawn_close_slots
    mov rax, [r15 + hp_G_ERROR]
    xor edx, edx
    jmp hp_acknowledge

hp_child_start:
    mov rdi, [r15 + hp_G_NULL_IN]
    xor esi, esi
    call hp_child_dup
    mov rdi, [r15 + hp_G_CHILD_OUT]
    mov esi, 1
    call hp_child_dup
    mov rdi, [r15 + hp_G_NULL_ERR]
    mov esi, 2
    call hp_child_dup
    lea rdi, [r15 + hp_G_SIGNAL]
    xor eax, eax
    mov ecx, 4
    rep stosq
    mov edi, 13
    lea rsi, [r15 + hp_G_SIGNAL]
    xor edx, edx
    mov r10d, 8
    mov eax, 13
    syscall
    test rax, rax
    js hp_child_error
    jmp hp_child_search
hp_child_error:
    neg rax
    mov [r15 + hp_G_EXEC_ERROR], rax
    mov rdi, [r15 + hp_G_ERR_OUT]
    lea rsi, [r15 + hp_G_EXEC_ERROR]
    mov edx, 8
hp_child_error_write:
    mov eax, 1
    syscall
    cmp rax, -4
    je hp_child_error_write
    mov edi, 1
    mov eax, 60
    syscall
