hp_child_dup:
    cmp rdi, 3
    jb hp_child_bad_descriptor
hp_child_dup_again:
    mov eax, 33
    syscall
    cmp rax, -4
    je hp_child_dup_again
    test rax, rax
    js hp_child_error
    ret
hp_child_bad_descriptor:
    mov rax, -9
    jmp hp_child_error

hp_close_slot:
    mov rax, [rdi]
    mov qword ptr [rdi], -1
    test rax, rax
    js hp_close_slot_empty
    mov rdi, rax
    mov eax, 3
    syscall
    ret
hp_close_slot_empty:
    xor eax, eax
    ret
hp_terminate_child:
