    cmp byte ptr [rsi], 80
    jne hp_path_environment_next
    cmp byte ptr [rsi + 1], 65
    jne hp_path_environment_next
    cmp byte ptr [rsi + 2], 84
    jne hp_path_environment_next
    cmp byte ptr [rsi + 3], 72
    jne hp_path_environment_next
