health_probe_cancel:
    push rbx
    push r15
    mov r15, rdi
    cmp qword ptr [r15 + HP_CANCELED], 1
    je hp_cancel_return
    mov qword ptr [r15 + HP_CANCELED], 1
    mov ebx, hp_G_OUT
hp_cancel_slots:
    lea rdi, [r15 + rbx]
    call hp_close_slot
    add ebx, 8
    cmp ebx, hp_G_ERR_OUT + 8
    jne hp_cancel_slots
    mov rdi, [r15 + hp_G_PID]
