    js hp_bad
    mov esi, 9
    mov eax, 62
    syscall
hp_cancel_return:
    xor eax, eax
    pop r15
    pop rbx
    ret
health_probe_reap:
    push r15
    mov r15, rdi
    cmp qword ptr [r15 + HP_CANCELED], 1
    jne hp_bad
    mov rdi, [r15 + hp_G_PID]
    test rdi, rdi
    jz hp_reap_done
    js hp_bad
    lea rsi, [r15 + hp_G_WAIT_STATUS]
