    test rax, rax
    jz hp_reap_pending
    js hp_bad
    cmp rax, [r15 + hp_G_PID]
    jne hp_bad
    mov qword ptr [r15 + hp_G_PID], 0
    mov qword ptr [r15 + hp_G_REAPED], 1
    mov eax, [r15 + hp_G_WAIT_STATUS]
    mov [r15 + hp_G_STATUS], rax
hp_reap_done:
    mov eax, 1
    pop r15
    ret
hp_reap_pending:
    xor eax, eax
    pop r15
    ret


