    mov [r14 + tk_MDW_W_REQUEST + 24], rax
    mov rax, [r14 + tk_MDW_W_KIND]
    mov [r14 + tk_MDW_W_REQUEST + 32], rax
    mov rax, [r14 + tk_MDW_W_SEQUENCE]
