    mov qword ptr [r14 + tk_MDW_W_REQUEST + 72], 0
    lea rdi, [r14 + tk_MDW_W_REQUEST]
    mov esi, 80
    lea rdx, [r14 + tk_MDW_W_SNAPSHOT]
    mov ecx, 128
    lea r8, [r14 + tk_MDW_W_POLICY]
    mov r9d, 256
    call tk_mdw_policy_native
    add rsp, 8
    ret
tk_mdw_policy_global:
