# Fixed owned-receiver adapter. The pool HIA remains the queue/receiver owner.
.equ PBA_MAGIC, 0x3130545741505348
.equ PBA_BYTES, 4096
.equ PBA_ROOT, 8
.equ PBA_OWNER, 16
.equ PBA_STATE, 24
.equ PBA_OUTPUT, 32
.equ PBA_CAPACITY, 40
.equ PBA_TOKEN, 64
.equ PBA_REPLY, 128
.equ PBA_RESULT, 320
.equ PBA_HEADER, 192
.equ PBA_MAXIMUM, 65728
.equ PBA_PENDING, 0xfffffff1
.equ PBA_ABANDONED, 0xfffffff2
.macro pba_enter
    push rbx
    push rbp
    push r12
    push r13
    push r14
    push r15
    sub rsp, 24
.endm
.macro pba_leave
    add rsp, 24
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbp
    pop rbx
    ret
.endm

# root, existing AsyncPool, immutable full token32, output, capacity.
# The caller generation is borrowed, not dropped by this one receiver.
# Return complete HRBPR001 + payload, or the distinct runtime-abandon marker.
public_async_pool_await:
    cmp r8, PBA_MAXIMUM
    jb pba_capacity
    test rdi, rdi
    jz pba_invalid
    test rsi, rsi
    jz pba_invalid
    test rdx, rdx
    jz pba_invalid
    test rcx, rcx
    jz pba_invalid
    mov rax, rcx
    add rax, PBA_MAXIMUM
    jc pba_invalid
    mov rax, [rdx]
    test rax, rax
    jz pba_invalid
