    mov r15, rdi
    mov r13, rsi
    mov r14, rdx
    mov rbp, rcx
    mov edi, PBA_BYTES
    call tk_allocate_guarded
    mov r12, rax
    mov rdx, PBA_MAGIC
    mov [r12], rdx
