    jne ap_contract
    mov rax, [r12 + PBA_TOKEN + 16]
    cmp [r13 + 48], rax
    jne ap_contract
    mov rax, [r12 + PBA_TOKEN + 24]
    cmp [r13 + 56], rax
    jne ap_contract
    cmp qword ptr [r13 + 64], 0
