    cmp [rbx + 72], rbp
    jne ap_contract
    mov rax, [rbx + 8]
    cmp rax, 3
    je stsub_no_receiver
    cmp rax, 4
    je stsub_no_receiver
    test rax, rax
    jz stsub_receiver
    cmp rax, 2
    jne ap_contract
stsub_receiver:
    cmp qword ptr [rbx + 96], 1
