    je stjournal_return
    cmp rax, PBA_HEADER
    jb ap_contract
    cmp rax, PBA_MAXIMUM
    ja ap_contract
    lea r13, [r12 + tk_ASY_CALL_OUTPUT_AT]
    cmp qword ptr [r13 + 8], 0
    jne ap_contract
    cmp qword ptr [r13 + 16], 12
    jne ap_contract
