    # Generic await retains all JoinOutcomes; the old observation HIA has no
    # arbitrary blocking JoinError renderer, which remains an explicit gap.
    cmp qword ptr [r13 + 104], 1
    jne ap_contract
    mov rbx, [r13 + 184]
    cmp rbx, 65536
    ja stjournal_refusal
    cmp [r13 + 80], rbx
    jne ap_contract
    cmp [rsp + 8], rbx
    jb ap_contract
    lea rsi, [r13 + PBA_HEADER]
    mov rdi, [rsp]
    mov rcx, rbx
    rep movsb
    mov rax, rbx
    jmp stjournal_return
stjournal_refusal:
    cmp qword ptr [r13 + 80], 0
    jne ap_contract
    cmp ebx, 0xffffffff
    je stjournal_refusal_ready
    cmp ebx, 0xfffffffe
    jne ap_contract
stjournal_refusal_ready:
    mov eax, ebx
stjournal_return:
    pba_leave


# One shared admission service. All symbols are local for relocation-free embedding.
.equ AM_CONTEXT_MAGIC, 0x313030434d415248
.equ AM_REQUEST_MAGIC, 0x313030514d415248
.equ AM_INITIAL_ARENA, 8192
.equ AM_MAX_ARENA, 33554432

# admission_create(rdi=trusted nonzero, never-reused service serial) -> rax=context or 0.
# The embedding owner retains this context until every caller/guard is retired.
admission_create:
    push rbp
    push rbx
    push r12
    push r13
    push r14
    push r15
    sub rsp, 8
    test rdi, rdi
    jz am_create_fail
    mov r13, rdi
    xor edi, edi
    mov esi, 8192
    mov edx, 3
    mov r10d, 0x22
    mov r8, -1
    xor r9d, r9d
    mov eax, 9
    syscall
    cmp rax, -4095
    jae am_create_fail
    mov r12, rax
    mov qword ptr [r12+32], -1
    lea rdi, [r12+4096]
    mov esi, 4096
    xor edx, edx
    mov eax, 10
    syscall
    test rax, rax
    jnz am_create_free_context
    xor edi, edi
    mov esi, AM_INITIAL_ARENA
    mov edx, 3
    mov r10d, 0x22
    mov r8, -1
    xor r9d, r9d
    mov eax, 9
    syscall
    cmp rax, -4095
    jae am_create_free_context
    mov [r12+16], rax
    mov qword ptr [r12+24], AM_INITIAL_ARENA
    xor edi, edi
    mov esi, 0x80800
    mov eax, 290
    syscall
    test rax, rax
    js am_create_free_arena
    mov [r12+32], rax
    mov [r12+8], r13
    movabs rax, AM_REQUEST_MAGIC
    mov [r12+128], rax
    mov qword ptr [r12+136], 1
    mov [r12+144], r13
    lea rdi, [r12+128]
    mov esi, 96
    lea rdx, [r12+256]
    mov ecx, 160
    mov r8, [r12+16]
    mov r9, [r12+24]
    call admission_invoke
    cmp rax, 160
    jne am_fatal
    movabs rax, AM_CONTEXT_MAGIC
    mov [r12], rax
    mov rax, r12
    jmp am_create_return
am_create_free_arena:
    mov rdi, [r12+16]
    mov rsi, [r12+24]
    mov eax, 11
    syscall
am_create_free_context:
    mov rdi, r12
    mov esi, 8192
    mov eax, 11
    syscall
am_create_fail:
    xor eax, eax
am_create_return:
    add rsp, 8
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

# admission_call(ctx, immutable request, request_bytes, reply, reply_capacity)
# -> eax=160 or an unchanged HIA/private rejection. Short gate contains HIA state,
# arena relocation and nonblocking notification only. No semantic waiting here.
admission_call:
    push rbp
    push rbx
    push r12
    push r13
    push r14
    push r15
    sub rsp, 104
    mov r12, rdi
    mov r13, rsi
    mov r14, rcx
    mov r15, r8
    cmp r8, 160
    jb am_call_capacity
    cmp rdx, 96
    jne am_call_invalid
    test r12, r12
    jz am_call_invalid
    movabs rax, AM_CONTEXT_MAGIC
    cmp [r12], rax
    jne am_call_invalid
    mov rdi, rsp
    mov rsi, r13
    mov ecx, 12
    cld
    rep movsq
    mov rdi, r12
    call am_gate_lock
am_call_retry:
    mov rdi, rsp
    mov esi, 96
    mov rdx, r14
    mov rcx, r15
    mov r8, [r12+16]
    mov r9, [r12+24]
    call admission_invoke
    mov edx, eax
    cmp rax, rdx
    jne am_fatal
    mov ebx, eax
    cmp eax, 0xfffffffe
    jne am_call_finish
    mov r13, [r12+24]
    cmp r13, AM_MAX_ARENA
    jae am_call_finish
    lea rbp, [r13+r13]
    cmp rbp, AM_MAX_ARENA
    ja am_fatal
    xor edi, edi
    mov rsi, rbp
    mov edx, 3
    mov r10d, 0x22
    mov r8, -1
    xor r9d, r9d
    mov eax, 9
    syscall
    cmp rax, -4095
    jae am_call_finish
    mov rdx, rax
    mov rdi, rax
    mov rsi, [r12+16]
    mov rcx, r13
    shr rcx, 3
    cld
    rep movsq
    mov rdi, [r12+16]
    mov [r12+16], rdx
    mov [r12+24], rbp
    mov rsi, r13
    mov eax, 11
    syscall
    test rax, rax
    jnz am_fatal
    jmp am_call_retry
am_call_finish:
    cmp ebx, 160
    jne am_call_unlock
    mov rax, [r12+16]
    cmp qword ptr [rax+88], 0
    je am_call_unlock
    mov qword ptr [rsp+96], 1
    mov rdi, [r12+32]
    lea rsi, [rsp+96]
    mov edx, 8
    mov eax, 1
    syscall
    cmp rax, 8
    je am_call_unlock
    cmp rax, -11
    je am_call_unlock
    cmp rax, -4
    je am_call_finish
    jmp am_fatal
am_call_unlock:
    mov rdi, r12
    call am_gate_unlock
    mov eax, ebx
    jmp am_call_return
am_call_capacity:
    mov eax, 0xfffffffe
    jmp am_call_return
am_call_invalid:
    mov eax, 0xffffffff
am_call_return:
    add rsp, 104
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

# Borrowed readiness fd; caller must remove epoll/poll registration before destroy.
admission_notification_fd:
    movabs rax, AM_CONTEXT_MAGIC
    cmp [rdi], rax
    jne am_fatal
    mov rax, [rdi+32]
    ret

# Only after op12 succeeds and all API callers have stopped/joined.
# Failed precondition returns STATE and changes no state. No invented Mutex::close.
admission_destroy:
    push rbx
    mov rbx, rdi
    movabs rax, AM_CONTEXT_MAGIC
    cmp [rbx], rax
    jne am_destroy_invalid
    call am_gate_lock
    mov rax, [rbx+16]
    cmp qword ptr [rax+96], 1
    jne am_destroy_busy
    mov qword ptr [rbx], 0
    mov rdi, [rbx+32]
    mov qword ptr [rbx+32], -1
    mov eax, 3
    syscall
    mov rdi, [rbx+16]
    mov rsi, [rbx+24]
    mov qword ptr [rbx+16], 0
    mov qword ptr [rbx+24], 0
    mov eax, 11
    syscall
    test rax, rax
    jnz am_fatal
    mov rdi, rbx
    mov esi, 8192
    mov eax, 11
    syscall
    test rax, rax
    jnz am_fatal
    xor eax, eax
    pop rbx
    ret
am_destroy_busy:
    mov rdi, rbx
    call am_gate_unlock
    mov eax, 0xfffffffd
    pop rbx
    ret
am_destroy_invalid:
    mov eax, 0xffffffff
    pop rbx
    ret

am_gate_lock:
    lea r8, [rdi+40]
am_gate_again:
    xor eax, eax
    mov edx, 1
    lock cmpxchg dword ptr [r8], edx
    je am_gate_locked
    mov rdi, r8
    mov esi, 128
    mov edx, 1
    xor r10d, r10d
    xor r9d, r9d
    mov eax, 202
    syscall
    cmp rax, -4
    je am_gate_again
    cmp rax, -11
    je am_gate_again
    test rax, rax
    jnz am_fatal
    jmp am_gate_again
am_gate_locked:
    ret

am_gate_unlock:
    add rdi, 40
    xor eax, eax
    xchg dword ptr [rdi], eax
    cmp eax, 1
    jne am_fatal
    mov esi, 129
    mov edx, 1
    xor r10d, r10d
    xor r8d, r8d
    xor r9d, r9d
    mov eax, 202
    syscall
    test rax, rax
    js am_fatal
    ret

admission_invoke:
    jmp qword ptr [rip + async_start_admission_image_slot]
.balign 8
async_start_admission_image_slot:
    .quad 0

am_fatal:
    mov edi, 70
    mov eax, 231
    syscall
    ud2


