# Canonical scheduler custody for the independent HIA shutdown continuation.

.macro asd_enter
    push rbx
    push rbp
    push r12
    push r13
    push r14
    push r15
    sub rsp, 24
.endm
.macro asd_leave
    add rsp, 24
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbp
    pop rbx
    ret
.endm

# Complete business shutdown before the separate actual runtime Drop.
asd_internal_task_drain:
    push rbx
    mov rbx, rdi
    call async_shutdown_run
    test rax, rax
    jnz ap_contract
    mov rdi, rbx
    pop rbx
    jmp asd_runtime_task_drain

