.equ CDF_ACTION_MAGIC, 0x3130414644435248
.equ CDF_COMPLETE_MAGIC, 0x31304f4344435248
.macro cdf_enter
    push rbp
    push rbx
    push r12
    push r13
    push r14
    push r15
    sub rsp, 72
.endm
.macro cdf_leave
    add rsp, 72
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret
.endm

