    movabs rax, CDF_CONTEXT_MAGIC
    mov [r12], rax
    mov rdi, rsp
    xor eax, eax
    mov ecx, 8
    rep stosq
    movabs rax, CDF_REQUEST_MAGIC
    mov [rsp], rax
    mov [rsp + 16], r13
    mov rdi, r12
    mov rsi, rsp
    mov edx, 64
    lea rcx, [r12 + 128]
    mov r8d, 64
    call cooperative_defer_call
    cmp rax, 64
    jne cdf_fatal
    mov rax, r12
    cdf_leave
